 import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, SRGBColorSpace, LinearFilter, LinearMipmapLinearFilter, DoubleSide } = ctx.THREE;

  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const width = 1.28;
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  material.side = DoubleSide;

  const mesh = new Mesh(geometry, material);
  mesh.userData.handlers = {};

  mesh.onBeforeRender = function (_renderer, _scene, camera) {
    this.quaternion.copy(camera.quaternion);
  };

  let cleaned = false;

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (cleaned) {
          tex.dispose();
          return;
        }
        tex.colorSpace = SRGBColorSpace;
        tex.minFilter = LinearMipmapLinearFilter;
        tex.magFilter = LinearFilter;

        material.map = tex;
        material.needsUpdate = true;

        const imgW = tex.image?.width || atlasRect.w;
        const imgH = tex.image?.height || atlasRect.h;

        const u1 = atlasRect.x / imgW;
        const v1 = atlasRect.y / imgH;
        const u2 = (atlasRect.x + atlasRect.w) / imgW;
        const v2 = (atlasRect.y + atlasRect.h) / imgH;

        const uv = geometry.attributes.uv;
        for (let i = 0; i < uv.count; i++) {
          const u = uv.getX(i);
          const v = uv.getY(i);
          uv.setXY(i, u1 + u * (u2 - u1), v1 + v * (v2 - v1));
        }
        uv.needsUpdate = true;
      })
      .catch(() => {
        material.color.set('#16161d');
      });
  } else {
    material.color.set('#16161d');
  }

  mesh.userData.cleanup = () => {
    cleaned = true;
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();
  };

  return mesh;
}
